def estimate_redis_ram_gb(entities=100_000_000, bytes_per_entity=400, repl_factor=2):
    raw_gb = (entities * bytes_per_entity) / (1024 ** 3)
    return round(raw_gb * repl_factor * 1.35, 2)  # 35% allocator & dict overhead

class FeatureMaterializer:
    def publish(self, entity_id, vector, ts):
        if not entity_id or ts <= 0:
            raise ValueError('Invalid entity or timestamp')
        self.redis_sink.upsert(entity_id, vector)
        self.iceberg_sink.append(entity_id, vector, ts)

def asof_join_partitioned(labels_df, features_df, lookback_days=30):
    return labels_df.join(
        features_df,
        (labels_df.entity_id == features_df.entity_id) &
        (features_df.ts <= labels_df.ts) &
        (features_df.ts >= labels_df.ts - F.expr(f'INTERVAL {lookback_days} DAYS')),
        how='left'
    )

def get_online_vector_safe(entity_id):
    cached = l1_cache.get(entity_id)
    if cached is not None:
        return cached
    try:
        vec = redis_breaker.call(redis_client.get, f'fv:{entity_id}')
        l1_cache.set(entity_id, vec, ttl=0.5)
        return vec
    except CircuitBreakerOpenError:
        return FALLBACK_MEDIANS

def evaluate_feature_health(null_rate, psi, lag_sec):
    if null_rate > 0.05 or psi > 0.25 or lag_sec > 300:
        model_router.enable_fallback_policy('baseline_v1')
        return 'DEGRADED'
    return 'HEALTHY'

def adaptive_backfill_write(batch, redis_monitor):
    if redis_monitor.read_p99_ms() > 3.0:
        time.sleep(0.25)  # Backoff to protect live inference
    rate_limiter.acquire(len(batch))
    redis_client.pipeline_set(batch)
